package com.aurora.assistant;
import android.app.Notification; import android.app.NotificationChannel; import android.app.NotificationManager; import android.app.PendingIntent; import android.app.Service;
import android.content.Intent; import android.content.SharedPreferences; import android.content.pm.PackageManager; import android.content.pm.ServiceInfo;
import android.os.Build; import android.os.Bundle; import android.os.Handler; import android.os.IBinder; import android.os.Looper;
import android.speech.RecognitionListener; import android.speech.RecognizerIntent; import android.speech.SpeechRecognizer; import java.util.ArrayList; import java.util.Locale;
public class AuroraAssistantService extends Service {
 public static final String ACTION_START="com.aurora.assistant.START", ACTION_STOP="com.aurora.assistant.STOP"; private static final String CHANNEL_ID="aurora_assistant_status"; private static final int NOTIFICATION_ID=7401;
 private final Handler handler=new Handler(Looper.getMainLooper()); private SpeechRecognizer recognizer; private boolean stopping=false, wakeDetected=false;
 @Override public void onCreate(){ super.onCreate(); if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O){ NotificationChannel c=new NotificationChannel(CHANNEL_ID,"AURORA Assistant",NotificationManager.IMPORTANCE_LOW); c.setDescription("Visible status for AURORA's microphone wake listener."); NotificationManager m=getSystemService(NotificationManager.class); if(m!=null)m.createNotificationChannel(c); } }
 @Override public int onStartCommand(Intent intent,int flags,int startId){ String action=intent==null?ACTION_START:intent.getAction(); if(ACTION_STOP.equals(action)){stopping=true;getSharedPreferences("aurora_assistant",MODE_PRIVATE).edit().putBoolean("wake_word_listening",false).apply();stopRecognition();stopForeground(true);stopSelf();return START_NOT_STICKY;} if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){stopSelf();return START_NOT_STICKY;} Notification n=buildNotification("Listening for Hey AURORA · tap to open"); if(Build.VERSION.SDK_INT>=29)startForeground(NOTIFICATION_ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE);else startForeground(NOTIFICATION_ID,n); stopping=false;wakeDetected=false;getSharedPreferences("aurora_assistant",MODE_PRIVATE).edit().putBoolean("wake_word_listening",true).apply();handler.post(this::listen);return START_STICKY; }
 private Notification buildNotification(String text){ Intent launch=getPackageManager().getLaunchIntentForPackage(getPackageName()); PendingIntent pi=launch==null?null:PendingIntent.getActivity(this,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0)); Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL_ID):new Notification.Builder(this); b.setContentTitle("AURORA · Hey AURORA").setContentText(text).setSmallIcon(getApplicationInfo().icon).setOngoing(true);if(pi!=null)b.setContentIntent(pi);return b.build(); }
 private void updateNote(String text){NotificationManager m=getSystemService(NotificationManager.class);if(m!=null)m.notify(NOTIFICATION_ID,buildNotification(text));}
 private void listen(){if(stopping||wakeDetected)return;if(!SpeechRecognizer.isRecognitionAvailable(this)){updateNote("Speech recognition unavailable · open AURORA to use mic");handler.postDelayed(this::listen,5000);return;}try{if(recognizer!=null){recognizer.destroy();recognizer=null;}recognizer=SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(new RecognitionListener(){
 public void onReadyForSpeech(Bundle b){} public void onBeginningOfSpeech(){} public void onRmsChanged(float r){} public void onBufferReceived(byte[] b){} public void onEndOfSpeech(){}
 public void onError(int e){if(!stopping&&!wakeDetected)handler.postDelayed(AuroraAssistantService.this::listen,1200);} public void onResults(Bundle b){check(b,true);} public void onPartialResults(Bundle b){check(b,false);} public void onEvent(int e,Bundle b){} });
 Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.UK.toLanguageTag());i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3);recognizer.startListening(i);}catch(Exception e){handler.postDelayed(this::listen,2500);} }
 private void check(Bundle b, boolean finalResult){if(b==null||stopping||wakeDetected)return;ArrayList<String> a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a==null)return;for(String s:a){String v=s==null?"":s.toLowerCase(Locale.UK).replaceAll("[^a-z ]"," ").replaceAll("\\s+"," ").trim();if(v.contains("hey aurora")||v.contains("hey a urora")||v.contains("hey orora")){wakeDetected=true;stopRecognition();getSharedPreferences("aurora_assistant",MODE_PRIVATE).edit().putBoolean("wake_detected",true).apply();updateNote("Wake phrase heard · opening AURORA");Intent launch=getPackageManager().getLaunchIntentForPackage(getPackageName());if(launch!=null){launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);startActivity(launch);}return;}}if(finalResult&&!stopping&&!wakeDetected)handler.postDelayed(this::listen,300);}
 private void stopRecognition(){handler.removeCallbacksAndMessages(null);if(recognizer!=null){try{recognizer.cancel();}catch(Exception e){}try{recognizer.destroy();}catch(Exception e){}recognizer=null;}}
 @Override public void onDestroy(){stopping=true;stopRecognition();super.onDestroy();} @Override public IBinder onBind(Intent i){return null;}
}